package dev.veyra.browser;
import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
final class HomeWidgets {
 final MainActivity a;JSONArray widgets;FrameLayout canvas;
 HomeWidgets(MainActivity owner){a=owner;try{widgets=new JSONArray(a.prefs.getString("homeWidgets","[{\"id\":\"clock\",\"kind\":\"clock\",\"style\":\"plain\",\"x\":0,\"y\":0,\"w\":1000,\"h\":180}]"));}catch(Exception e){widgets=new JSONArray();}}
 String name(String kind){switch(kind){case "clock":return a.t("Часы","Clock","Годинник");case "calendar":return a.t("Календарь","Calendar","Календар");case "notes":return a.t("Заметки","Notes","Нотатки");case "focus":return a.t("Таймер","Timer","Таймер");default:return a.t("Недавние запросы","Recent searches","Недавні запити");}}
 final Runnable persist=this::flush;
 void save(){a.uiHandler.removeCallbacks(persist);a.uiHandler.postDelayed(persist,300);}
 void flush(){a.uiHandler.removeCallbacks(persist);a.prefs.edit().putString("homeWidgets",widgets.toString()).apply();}
 View view(){canvas=new FrameLayout(a);canvas.setClipChildren(false);canvas.setLayoutParams(new LinearLayout.LayoutParams(-1,a.dp(200)));canvas.post(this::render);return canvas;}
 void render(){if(canvas==null||canvas.getWidth()==0)return;canvas.removeAllViews();int bottom=0;for(int i=0;i<widgets.length();i++){JSONObject w=widgets.optJSONObject(i);if(w==null)continue;String kind=w.optString("kind");int y=Math.max(0,Math.min(2000,w.optInt("y",i*200))),h=Math.max(150,Math.min(800,w.optInt("h",180))),width=Math.max(400,Math.min(1000,w.optInt("w",1000))),x=Math.max(0,Math.min(1000-width,w.optInt("x",0)));LinearLayout box=a.column();box.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(10));box.setBackground(a.rounded(w.optString("style").equals("accent")?android.graphics.Color.rgb(49,40,67):a.surface,20));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(canvas.getWidth()*width/1000,a.dp(h));lp.leftMargin=canvas.getWidth()*x/1000;lp.topMargin=a.dp(y);canvas.addView(box,lp);TextView handle=a.label(name(kind),12,a.muted);handle.setPadding(0,a.dp(5),0,a.dp(10));box.addView(handle);drag(handle,box,w,false);
 if(kind.equals("clock")){TextClock clock=new TextClock(a);clock.setFormat12Hour("h:mm a");clock.setFormat24Hour("HH:mm");clock.setTextSize(44);clock.setTextColor(a.text);box.addView(clock);box.addView(a.label(java.text.DateFormat.getDateInstance(java.text.DateFormat.FULL).format(new Date()),12,a.muted));}
 else if(kind.equals("calendar")){Calendar now=Calendar.getInstance(),first=(Calendar)now.clone();first.set(Calendar.DAY_OF_MONTH,1);StringBuilder days=new StringBuilder();int offset=(first.get(Calendar.DAY_OF_WEEK)+5)%7;for(int d=0;d<offset;d++)days.append("   ");for(int d=1;d<=now.getActualMaximum(Calendar.DAY_OF_MONTH);d++){days.append(String.format(Locale.ROOT,"%2d ",d));if((d+offset)%7==0)days.append('\n');}TextView text=a.label(new java.text.SimpleDateFormat("MMMM yyyy",new Locale(a.lang)).format(new Date())+"\n"+days,14,a.text);text.setTypeface(android.graphics.Typeface.MONOSPACE);box.addView(text);}
 else if(kind.equals("notes")){EditText note=new EditText(a);note.setText(w.optString("note"));note.setTextColor(a.text);note.setTextSize(15);note.setBackgroundColor(android.graphics.Color.TRANSPARENT);note.setGravity(Gravity.TOP);note.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4000)});box.addView(note,new LinearLayout.LayoutParams(-1,0,1));note.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int c){try{w.put("note",s.toString());save();}catch(JSONException ignored){}}public void afterTextChanged(Editable s){}});}
 else if(kind.equals("focus")){TextView time=a.label("25:00",40,a.text);box.addView(time);Button start=new Button(a);start.setText(a.t("Начать","Start","Почати"));box.addView(start);start.setOnClickListener(v->{long end=System.currentTimeMillis()+25*60000;Runnable tick=new Runnable(){public void run(){if(!time.isAttachedToWindow())return;long seconds=Math.max(0,(end-System.currentTimeMillis())/1000);time.setText(String.format(Locale.ROOT,"%02d:%02d",seconds/60,seconds%60));if(seconds>0)time.postDelayed(this,1000);else start.setEnabled(true);}};start.setEnabled(false);time.post(tick);});}
 else {try{JSONArray recent=new JSONArray(a.selected!=null&&a.selected.privateMode?"[]":a.prefs.getString("recentSearches","[]"));for(int r=0;r<Math.min(4,recent.length());r++){String query=recent.optString(r);TextView item=a.label(query,14,a.text);item.setSingleLine();item.setEllipsize(android.text.TextUtils.TruncateAt.END);item.setPadding(0,a.dp(5),0,a.dp(5));box.addView(item);item.setOnClickListener(v->a.navigate(query));}}catch(JSONException ignored){}}
 MainActivity.Icon resize=a.new Icon("resize");resize.setContentDescription(a.t("Изменить размер","Resize","Змінити розмір"));LinearLayout.LayoutParams gripParams=new LinearLayout.LayoutParams(a.dp(28),a.dp(24));gripParams.gravity=Gravity.RIGHT;box.addView(resize,gripParams);drag(resize,box,w,true);bottom=Math.max(bottom,y+h+14);
 }canvas.getLayoutParams().height=a.dp(Math.max(200,bottom));canvas.requestLayout();}
 void drag(View handle,View box,JSONObject w,boolean resize){handle.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int x,y,width,height;public boolean onTouch(View v,android.view.MotionEvent event){FrameLayout.LayoutParams lp=(FrameLayout.LayoutParams)box.getLayoutParams();switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:sx=event.getRawX();sy=event.getRawY();x=lp.leftMargin;y=lp.topMargin;width=lp.width;height=lp.height;v.getParent().requestDisallowInterceptTouchEvent(true);box.bringToFront();return true;case MotionEvent.ACTION_MOVE:float dx=event.getRawX()-sx,dy=event.getRawY()-sy;if(resize){lp.width=Math.max(a.dp(140),Math.min(canvas.getWidth()-x,width+(int)dx));lp.height=Math.max(a.dp(150),Math.min(a.dp(800),height+(int)dy));}else{lp.leftMargin=Math.max(0,Math.min(canvas.getWidth()-width,x+(int)dx));lp.topMargin=Math.max(0,Math.min(a.dp(2000),y+(int)dy));}box.setLayoutParams(lp);canvas.getLayoutParams().height=Math.max(canvas.getHeight(),lp.topMargin+lp.height+a.dp(16));canvas.requestLayout();return true;case MotionEvent.ACTION_UP:try{w.put("x",lp.leftMargin*1000/canvas.getWidth()).put("y",Math.round(lp.topMargin/a.getResources().getDisplayMetrics().density)).put("w",lp.width*1000/canvas.getWidth()).put("h",Math.round(lp.height/a.getResources().getDisplayMetrics().density));save();}catch(JSONException ignored){}v.getParent().requestDisallowInterceptTouchEvent(false);v.performClick();return true;case MotionEvent.ACTION_CANCEL:v.getParent().requestDisallowInterceptTouchEvent(false);render();return true;default:return false;}}});}
 void store(){LinearLayout body=a.openSheet(a.t("Виджеты","Widgets","Віджети"));for(String kind:new String[]{"clock","calendar","notes","focus","recent"})a.action(body,name(kind),a.t("Добавить","Add","Додати"),()->{if(widgets.length()>=12){a.message(a.t("Максимум 12 виджетов","Maximum 12 widgets","Максимум 12 віджетів"));return;}try{int y=0;for(int i=0;i<widgets.length();i++){JSONObject w=widgets.getJSONObject(i);y=Math.max(y,w.optInt("y",i*200)+w.optInt("h",180)+14);}widgets.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("kind",kind).put("style","plain").put("x",0).put("y",Math.min(2000,y)).put("w",1000).put("h",200));save();a.sheet.dismiss();a.showHome();}catch(JSONException ignored){}});
 for(int i=0;i<widgets.length();i++){final int index=i;JSONObject w=widgets.optJSONObject(i);if(w==null)continue;a.action(body,name(w.optString("kind")),a.t("Настроить или удалить","Customize or remove","Налаштувати або видалити"),()->edit(index));}
 a.action(body,a.t("Сообщество","Community","Спільнота"),a.t("Бесплатные оформления виджетов","Free widget designs","Безкоштовні оформлення віджетів"),this::community);
 }
 void edit(int index){JSONObject w=widgets.optJSONObject(index);if(w==null)return;LinearLayout body=a.openSheet(name(w.optString("kind")));for(String style:new String[]{"plain","glass","accent"})a.action(body,style.equals("plain")?a.t("Обычный","Plain","Звичайний"):style.equals("glass")?a.t("Стекло","Glass","Скло"):a.t("Акцент","Accent","Акцент"),"",()->{try{w.put("style",style);save();a.sheet.dismiss();a.showHome();}catch(JSONException ignored){}});a.action(body,a.t("Опубликовать оформление","Publish design","Опублікувати оформлення"),a.t("Текст заметок не отправляется","Notes are not uploaded","Текст нотаток не надсилається"),()->publish(w));a.action(body,a.t("Удалить","Remove","Видалити"),"",()->{widgets.remove(index);save();a.sheet.dismiss();a.showHome();});}
 void publish(JSONObject w){if(!a.sync.signedIn()){a.showSync();return;}LinearLayout body=a.openSheet(a.t("Опубликовать виджет","Publish widget","Опублікувати віджет"));EditText title=a.syncInput(body,a.t("Название","Title","Назва"),false),description=a.syncInput(body,a.t("Описание","Description","Опис"),false);title.setInputType(android.text.InputType.TYPE_CLASS_TEXT);description.setInputType(android.text.InputType.TYPE_CLASS_TEXT);a.action(body,a.t("Опубликовать","Publish","Опублікувати"),"",()->{String t=title.getText().toString().trim(),d=description.getText().toString();if(t.isEmpty()||t.length()>60||d.length()>240){a.message(a.t("Название: 1–60 символов, описание: до 240","Title: 1–60 characters, description: up to 240","Назва: 1–60 символів, опис: до 240"));return;}a.syncWork(()->{JSONObject template=new JSONObject().put("kind",w.optString("kind")).put("style",w.optString("style")).put("wide",false).put("hour12",false);a.sync.request("widget-publish",new JSONObject().put("title",t).put("description",d).put("template",template),true);return a.t("Опубликовано","Published","Опубліковано");});});}
 void community(){LinearLayout body=a.openSheet(a.t("Сообщество","Community","Спільнота"));TextView status=a.label(a.t("Загрузка…","Loading…","Завантаження…"),14,a.muted);body.addView(status);new Thread(()->{try{JSONArray list=a.sync.request("widget-list",new JSONObject(),a.sync.signedIn()).getJSONArray("widgets");a.runOnUiThread(()->{if(!body.isAttachedToWindow())return;body.removeView(status);for(int i=0;i<list.length();i++){JSONObject item=list.optJSONObject(i);if(item==null)continue;JSONObject template=item.optJSONObject("template");if(template==null||!Arrays.asList("clock","calendar","notes","focus","recent").contains(template.optString("kind"))||!Arrays.asList("plain","glass","accent").contains(template.optString("style")))continue;a.action(body,item.optString("title"),item.optString("description"),()->{try{if(widgets.length()>=12)return;widgets.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("kind",template.optString("kind")).put("style",template.optString("style")).put("x",0).put("y",Math.min(2000,widgets.length()*214)).put("w",1000).put("h",200));save();a.sheet.dismiss();a.showHome();}catch(JSONException ignored){}});if(item.optBoolean("owned"))a.action(body,a.t("Удалить публикацию","Remove publication","Видалити публікацію"),"",()->a.syncWork(()->{a.sync.request("widget-delete",new JSONObject().put("id",item.optString("id")),true);return a.t("Удалено","Removed","Видалено");}));}});}catch(Exception e){a.runOnUiThread(()->status.setText(a.t("Не удалось загрузить коллекцию","Could not load collection","Не вдалося завантажити колекцію")));}},"Veyra widgets").start();}
}
